#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set the two totals to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Target repo for every gh secret set/list below (GH_REPO is honoured by gh).
export GH_REPO=hexuria/buwiz-forms

EXPECTED_IDENTITY="Developer ID Application: Goldcoders Corp (5KZ8MD34QW)"

# die "message" — fatal stage failure, in red.
die() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }

TOTAL_STAGES=4
TOTAL_MINUTES=20

banner "eBIRForms macOS release secrets"

# ── Stage 1 ─────────────────────────────────────────────────────────────────
stage "Prerequisites" 2

say "This wizard configures the five secrets release-macos.yml needs:"
say "  APPLE_CERTIFICATE_P12, APPLE_CERTIFICATE_PASSWORD,"
say "  APPLE_API_KEY_P8, APPLE_API_KEY_ID, APPLE_API_ISSUER_ID"
say "plus the optional GOOGLE_CLIENT_ID / GOOGLE_CLIENT_SECRET."
say ""

if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  printf '  %s✓%s gh CLI is authenticated\n' "$GREEN" "$RESET"
else
  warn "gh CLI is missing or not authenticated — run: gh auth login"
  SKIPPED+=("gh authentication (run: gh auth login)")
fi

if security find-identity -v -p codesigning 2>/dev/null \
  | grep -F "$EXPECTED_IDENTITY" >/dev/null 2>&1; then
  printf '  %s✓%s found signing identity: %s\n' "$GREEN" "$RESET" "$EXPECTED_IDENTITY"
else
  warn "no '$EXPECTED_IDENTITY' identity in your keychains"
  note "install the Developer ID Application certificate + private key in the"
  note "login keychain first (developer.apple.com → Certificates), then re-run."
fi

pause "Ready to export the certificate?"

# ── Stage 2 ─────────────────────────────────────────────────────────────────
stage "Developer ID certificate (.p12)" 6

say "Export the Developer ID Application identity as a .p12:"
open -a "Keychain Access" || true
step "In Keychain Access: select the 'login' keychain → 'My Certificates'."
step "Select ONLY '$EXPECTED_IDENTITY'."
note "expand it first — a private key must be nested underneath; if there is"
note "none, the cert alone cannot sign and the export is useless."
step "Right-click → Export… → format 'Personal Information Exchange (.p12)'."
step "Save it somewhere temporary, e.g. ~/Desktop/goldcoders-developer-id.p12."
step "Set a strong export password when prompted — it becomes a CI secret."

ask MACOS_P12_PATH "Path to the exported .p12:"
MACOS_P12_PATH="${MACOS_P12_PATH/#\~/$HOME}"
if [[ ! -f "$MACOS_P12_PATH" ]]; then
  die "no file at $MACOS_P12_PATH"
fi
ask_secret MACOS_P12_PASSWORD "Export password for that .p12:"
export MACOS_P12_PASSWORD  # openssl reads it via -passin env:

# OpenSSL 3.x needs -legacy for the RC2 encryption Keychain Access writes;
# LibreSSL (the macOS /usr/bin/openssl) parses it without the flag.
P12_LEGACY=()
if ! /usr/bin/openssl pkcs12 -in "$MACOS_P12_PATH" \
    -passin env:MACOS_P12_PASSWORD -noout 2>/dev/null; then
  if /usr/bin/openssl pkcs12 -legacy -in "$MACOS_P12_PATH" \
      -passin env:MACOS_P12_PASSWORD -noout 2>/dev/null; then
    P12_LEGACY=(-legacy)
  else
    unset MACOS_P12_PASSWORD
    die "could not parse $MACOS_P12_PATH — wrong password or not a .p12?"
  fi
fi

P12_SUBJECT="$(/usr/bin/openssl pkcs12 "${P12_LEGACY[@]+"${P12_LEGACY[@]}"}" \
  -in "$MACOS_P12_PATH" -passin env:MACOS_P12_PASSWORD -clcerts -nokeys 2>/dev/null \
  | /usr/bin/openssl x509 -noout -subject 2>/dev/null || true)"
case "$P12_SUBJECT" in
  *"Goldcoders Corp"*5KZ8MD34QW*) ;;
  *)
    unset MACOS_P12_PASSWORD
    note "  ${P12_SUBJECT:-<could not read subject>}"
    die "certificate subject is not the Goldcoders Corp Developer ID"
    ;;
esac

P12_KEY="$(/usr/bin/openssl pkcs12 "${P12_LEGACY[@]+"${P12_LEGACY[@]}"}" \
  -in "$MACOS_P12_PATH" -passin env:MACOS_P12_PASSWORD -nocerts -nodes 2>/dev/null || true)"
if ! printf '%s' "$P12_KEY" | grep -q "PRIVATE KEY"; then
  unset MACOS_P12_PASSWORD
  die "the .p12 contains no private key — re-export from 'My Certificates'"
fi

P12_CERTS="$(/usr/bin/openssl pkcs12 "${P12_LEGACY[@]+"${P12_LEGACY[@]}"}" \
  -in "$MACOS_P12_PATH" -passin env:MACOS_P12_PASSWORD -nokeys 2>/dev/null || true)"
DEV_ID_COUNT="$(printf '%s\n' "$P12_CERTS" \
  | grep -c 'subject=.*Developer ID Application' || true)"
if [[ "$DEV_ID_COUNT" != "1" ]]; then
  unset MACOS_P12_PASSWORD
  die "expected exactly one 'Developer ID Application' cert in the .p12, found $DEV_ID_COUNT — re-export selecting only the one identity"
fi
printf '  %s✓%s .p12 holds the expected certificate and its private key\n' \
  "$GREEN" "$RESET"

set_secret APPLE_CERTIFICATE_P12 "$(base64 -i "$MACOS_P12_PATH")"
set_secret APPLE_CERTIFICATE_PASSWORD "$MACOS_P12_PASSWORD"
unset MACOS_P12_PASSWORD

if confirm "Delete the exported .p12 now ($MACOS_P12_PATH)?"; then
  rm -P "$MACOS_P12_PATH" 2>/dev/null || rm -f "$MACOS_P12_PATH"
  printf '  %s✓%s deleted %s\n' "$GREEN" "$RESET" "$MACOS_P12_PATH"
else
  SKIPPED+=("delete $MACOS_P12_PATH yourself once the secrets work")
fi

# ── Stage 3 ─────────────────────────────────────────────────────────────────
stage "App Store Connect API key (notarization)" 8

say "Notarization authenticates with an App Store Connect API key (.p8)."
say ""
say "If you already have one, press Enter to keep the saved defaults."
say "If not:"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Users and Access → Integrations → App Store Connect API → Team Keys."
step "Click '+' to generate a key (Developer access or higher)."
step "Download the .p8 — Apple serves it exactly once — and note the"
step "Key ID (10 chars) and the Issuer ID (UUID at the top of the page)."

ask APP_STORE_KEY_ID "Key ID:"
ask APP_STORE_ISSUER_ID "Issuer ID:"
ask APP_STORE_P8_PATH "Path to the AuthKey .p8 file:"
APP_STORE_P8_PATH="${APP_STORE_P8_PATH/#\~/$HOME}"

if [[ ! -f "$APP_STORE_P8_PATH" ]]; then
  die "no file at $APP_STORE_P8_PATH"
fi

say "Validating the key against the Notary service (read-only history call)…"
if ! xcrun notarytool history \
    --key "$APP_STORE_P8_PATH" \
    --key-id "$APP_STORE_KEY_ID" \
    --issuer "$APP_STORE_ISSUER_ID" >/dev/null 2>&1; then
  die "the Notary service rejected this key — check the Key ID, Issuer ID and that you picked the right .p8 file, then re-run the wizard"
fi
printf '  %s✓%s notarytool accepted the credentials\n' "$GREEN" "$RESET"

set_secret APPLE_API_KEY_ID "$APP_STORE_KEY_ID"
set_secret APPLE_API_ISSUER_ID "$APP_STORE_ISSUER_ID"
set_secret APPLE_API_KEY_P8 "$(cat "$APP_STORE_P8_PATH")"
note "keep $APP_STORE_P8_PATH — Apple will not let you download it again"

# ── Stage 4 ─────────────────────────────────────────────────────────────────
stage "Google OAuth (optional)" 4

say "release-macos.yml bakes GOOGLE_CLIENT_ID / GOOGLE_CLIENT_SECRET into the"
say "binary via option_env!. Missing values only downgrade the build to a"
say "warning — it still ships."
if confirm "Set the Google OAuth secrets now?"; then
  ask GOOGLE_CLIENT_ID "Google client ID:"
  ask_secret GOOGLE_CLIENT_SECRET "Google client secret:"
  set_secret GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  set_secret GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
else
  SKIPPED+=("GOOGLE_CLIENT_ID / GOOGLE_CLIENT_SECRET (build warns without them)")
fi

finish

if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  say "GitHub secrets now on $GH_REPO:"
  gh secret list 2>/dev/null | awk '{print "  - " $1}' || true
  say ""
fi
say "Dry-run the pipeline end to end (builds + signs + notarizes, never publishes):"
say "  gh workflow run release-macos.yml --ref main"
